                module AntichristPatternC0E
                ; Документация [исходная композиция](../../../../Docs/MusicComposition.md)
                assert $ == #F4BE
                ; Общий физический поток, ссылки 14C
Row00:          DB #F0, #0A                                                     ; орнамент 0, следующий байт является уже удвоенным индексом сэмпла
                DB #BD, #00, #75                                                ; форма огибающей 12, период старшим байтом вперёд
                DB #B1, #03                                                     ; перезагрузка длительности строки
                DB #6F                                                          ; нота с индексом #1F, завершение строки
Row01:          DB #B1, #01                                                     ; перезагрузка длительности строки
                DB #C0                                                          ; выключение ноты и завершение строки
Row02:          DB #10, #0C                                                     ; снятие маски огибающей и сырой удвоенный индекс сэмпла
                DB #B1, #04                                                     ; перезагрузка длительности строки
                DB #A6                                                          ; нота с индексом #56, завершение строки
Row03:          DB #1E, #00, #3B, #08                                           ; форма огибающей 14, старший и младший период, сырой индекс сэмпла
                DB #B1, #02                                                     ; перезагрузка длительности строки
                DB #72                                                          ; нота с индексом #22, завершение строки
Row04:          DB #D3                                                          ; выбор сэмпла 3
                DB #66                                                          ; нота с индексом #16, завершение строки
Row05:          DB #1C, #00, #75, #0C                                           ; форма огибающей 12, старший и младший период, сырой индекс сэмпла
                DB #B1, #04                                                     ; перезагрузка длительности строки
                DB #A6                                                          ; нота с индексом #56, завершение строки
Row06:          DB #08                                                          ; отложенный эффект #08, параметры читаются после терминатора
                DB #B1, #08                                                     ; перезагрузка длительности строки
                DB #D0                                                          ; завершение строки без новой ноты
                DB #01, #06, #00                                                ; параметры отложенного эффекта #08, порядок RET от последнего к первому
Row07:          DB #10, #08                                                     ; снятие маски огибающей и сырой удвоенный индекс сэмпла
                DB #B1, #04                                                     ; перезагрузка длительности строки
                DB #72                                                          ; нота с индексом #22, завершение строки
Row08:          DB #1E, #00, #3B, #0C                                           ; форма огибающей 14, старший и младший период, сырой индекс сэмпла
                DB #B1, #02                                                     ; перезагрузка длительности строки
                DB #A6                                                          ; нота с индексом #56, завершение строки
Row09:          DB #D3                                                          ; выбор сэмпла 3
                DB #66                                                          ; нота с индексом #16, завершение строки
Row0A:          DB #1C, #00, #5D, #0A                                           ; форма огибающей 12, старший и младший период, сырой индекс сэмпла
                DB #B1, #03                                                     ; перезагрузка длительности строки
                DB #6F                                                          ; нота с индексом #1F, завершение строки
Row0B:          DB #B1, #01                                                     ; перезагрузка длительности строки
                DB #C0                                                          ; выключение ноты и завершение строки
Row0C:          DB #10, #0C                                                     ; снятие маски огибающей и сырой удвоенный индекс сэмпла
                DB #B1, #04                                                     ; перезагрузка длительности строки
                DB #A6                                                          ; нота с индексом #56, завершение строки
Row0D:          DB #1E, #00, #2F, #08                                           ; форма огибающей 14, старший и младший период, сырой индекс сэмпла
                DB #B1, #02                                                     ; перезагрузка длительности строки
                DB #72                                                          ; нота с индексом #22, завершение строки
Row0E:          DB #D3                                                          ; выбор сэмпла 3
                DB #6A                                                          ; нота с индексом #1A, завершение строки
Row0F:          DB #1C, #00, #5D, #0C                                           ; форма огибающей 12, старший и младший период, сырой индекс сэмпла
                DB #B1, #04                                                     ; перезагрузка длительности строки
                DB #A6                                                          ; нота с индексом #56, завершение строки
Row10:          DB #08                                                          ; отложенный эффект #08, параметры читаются после терминатора
                DB #B1, #08                                                     ; перезагрузка длительности строки
                DB #D0                                                          ; завершение строки без новой ноты
                DB #01, #06, #00                                                ; параметры отложенного эффекта #08, порядок RET от последнего к первому
Row11:          DB #10, #08                                                     ; снятие маски огибающей и сырой удвоенный индекс сэмпла
                DB #B1, #04                                                     ; перезагрузка длительности строки
                DB #72                                                          ; нота с индексом #22, завершение строки
Row12:          DB #1E, #00, #2F, #0C                                           ; форма огибающей 14, старший и младший период, сырой индекс сэмпла
                DB #B1, #02                                                     ; перезагрузка длительности строки
                DB #A6                                                          ; нота с индексом #56, завершение строки
Row13:          DB #D3                                                          ; выбор сэмпла 3
                DB #6A                                                          ; нота с индексом #1A, завершение строки
End:            DB #00                                                          ; исходный нулевой байт физической границы потока, переход позиции описан в MusicPattern.md
                assert $ == #F528
                endmodule
